import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    idx = 0
    N = data[idx]
    idx += 1

    dice = []
    for _ in range(N):
        K = data[idx]
        idx += 1

        freq = {}
        for _ in range(K):
            a = data[idx]
            idx += 1
            freq[a] = freq.get(a, 0) + 1

        dice.append((len(freq), K, freq, list(freq.items())))

    # Iterate over the smaller distinct-value dictionary for each pair.
    dice.sort(key=lambda x: x[0])

    ans = 0.0

    for i in range(N):
        _, ki, _, items_i = dice[i]

        for j in range(i + 1, N):
            _, kj, dj, _ = dice[j]

            get = dj.get
            common_weight = 0

            for a, c in items_i:
                common_weight += c * get(a, 0)

            if common_weight:
                prob = common_weight / (ki * kj)
                if prob > ans:
                    ans = prob

    print(f"{ans:.15f}")

if __name__ == "__main__":
    main()

